-- Table: hrm_leave_request_detail
-- Source: accounting_admin_db.sql (7. HRMIS)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS hrm_leave_request_detail (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    leave_request_id  BIGINT NOT NULL REFERENCES hrm_leave_request(id) ON DELETE CASCADE,
    line_number       INTEGER NOT NULL CHECK (line_number > 0),
    leave_date        DATE NOT NULL,
    day_type          VARCHAR(20) NOT NULL DEFAULT 'full'
                      CHECK (day_type IN ('full', 'half')),
    notes             TEXT,
    UNIQUE (leave_request_id, line_number)
);
